1	// Package settings provides configuration loading for Entire.
2	// This package is separate from cli to allow strategy package to import it
3	// without creating an import cycle (cli imports strategy).
4	package settings
5	
6	import (
7		"bytes"
8		"context"
9		"encoding/json"
10		"fmt"
11		"os"
12		"path/filepath"
13		"strings"
14		"time"
15	
16		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
17		"github.com/entireio/cli/cmd/entire/cli/paths"
18	)
19	
20	const (
21		// EntireSettingsFile is the path to the Entire settings file
22		EntireSettingsFile = ".entire/settings.json"
23		// EntireSettingsLocalFile is the path to the local settings override file (not committed)
24		EntireSettingsLocalFile = ".entire/settings.local.json"
25		// defaultGenerationRetentionDays is the default retention window for archived
26		// checkpoints v2 raw-transcript generations when no override is configured.
27		defaultGenerationRetentionDays = 60
28	)
29	
30	// Commit linking mode constants.
31	const (
32		// CommitLinkingAlways auto-links commits to sessions without prompting.
33		CommitLinkingAlways = "always"
34		// CommitLinkingPrompt prompts the user on each commit (default for existing users).
35		CommitLinkingPrompt = "prompt"
36	)
37	
38	// EntireSettings represents the .entire/settings.json configuration
39	type EntireSettings struct {
40		// Enabled indicates whether Entire is active. When false, CLI commands
41		// show a disabled message and hooks exit silently. Defaults to true.
42		Enabled bool `json:"enabled"`
43	
44		// LocalDev indicates whether to use "go run" instead of the "entire" binary
45		// This is used for development when the binary is not installed
46		LocalDev bool `json:"local_dev,omitempty"`
47	
48		// LogLevel sets the logging verbosity (debug, info, warn, error).
49		// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
50		// Defaults to "info".
51		LogLevel string `json:"log_level,omitempty"`
52	
53		// StrategyOptions contains strategy-specific configuration
54		StrategyOptions map[string]any `json:"strategy_options,omitempty"`
55	
56		// AbsoluteGitHookPath embeds the full binary path in git hooks instead of
57		// bare "entire". This is needed for GUI git clients (Xcode, Tower, etc.)
58		// that don't source shell profiles and can't find "entire" on PATH.
59		AbsoluteGitHookPath bool `json:"absolute_git_hook_path,omitempty"`
60	
61		// Telemetry controls anonymous usage analytics.
62		// nil = not asked yet (show prompt), true = opted in, false = opted out
63		Telemetry *bool `json:"telemetry,omitempty"`
64	
65		// Redaction configures PII redaction behavior for transcripts and metadata.
66		Redaction *RedactionSettings `json:"redaction,omitempty"`
67	
68		// CommitLinking controls how commits are linked to agent sessions.
69		// "always" = auto-link without prompting, "prompt" = ask on each commit.
70		// Defaults to "prompt" (preserves existing user behavior).
71		CommitLinking string `json:"commit_linking,omitempty"`
72	
73		// ExternalAgents enables discovery and registration of external agent
74		// plugins (entire-agent-* binaries on $PATH). Defaults to false.
75		ExternalAgents bool `json:"external_agents,omitempty"`
76	
77		// SummaryGeneration stores provider preferences for explain --generate.
78		// This is separate from strategy_options.summarize, which controls
79		// checkpoint auto-summarize behavior.
80		SummaryGeneration *SummaryGenerationSettings `json:"summary_generation,omitempty"`
81	
82		// Vercel indicates that the repository uses Vercel and the metadata branch
83		// should include a vercel.json that disables deployments for Entire branches.
84		Vercel bool `json:"vercel,omitempty"`
85	
86		// SummaryTimeoutSeconds is an optional hard deadline (in seconds) for
87		// `entire explain --generate` summary generation. Zero or negative means
88		// "unset" -- the caller picks the default. Not yet consumed by the
89		// generate path; present so settings round-trip for a follow-up change
90		// that wires it into the deadline selection.
91		SummaryTimeoutSeconds int `json:"summary_timeout_seconds,omitempty"`
92	
93		// SignCheckpointCommits controls whether checkpoint commits are signed.
94		// nil/true = sign (default), false = skip signing.
95		SignCheckpointCommits *bool `json:"sign_checkpoint_commits,omitempty"`
96	
97		// Deprecated: no longer used. Exists to tolerate old settings files
98		// that still contain "strategy": "auto-commit" or similar.
99		Strategy string `json:"strategy,omitempty"`
100	}
101	
102	// SummaryGenerationSettings configures provider selection for on-demand
103	// checkpoint summaries generated by explain --generate.
104	type SummaryGenerationSettings struct {
105		// Provider is the selected summary provider agent name
106		// (for example "claude-code", "codex", or "gemini").
107		Provider string `json:"provider,omitempty"`
108	
109		// Model is an optional model hint passed to the selected provider.
110		Model string `json:"model,omitempty"`
111	}
112	
113	// Validate returns an error if the settings combination is semantically invalid.
114	// A model without a provider is meaningless: the model hint needs a provider to
115	// route to. The load path calls Validate() after merging, catching hand-edited
116	// files that land in this state.
117	func (s *SummaryGenerationSettings) Validate() error {
118		if s == nil {
119			return nil
120		}
121		if s.Model != "" && s.Provider == "" {
122			return fmt.Errorf("summary_generation.model %q set without summary_generation.provider", s.Model)
123		}
124		return nil
125	}
126	
127	// SetProvider updates the provider and optionally the model, clearing any stale
128	// model from the previous provider when switching without a replacement.
129	// An empty newProvider preserves the current provider; an empty newModel
130	// preserves the current model unless the provider is changing, in which case
131	// the old model is cleared to avoid passing (say) a Claude model to Codex.
132	func (s *SummaryGenerationSettings) SetProvider(newProvider, newModel string) {
133		if s == nil {
134			return
135		}
136		if newProvider != "" && s.Provider != "" && s.Provider != newProvider && newModel == "" {
137			s.Model = ""
138		}
139		if newProvider != "" {
140			s.Provider = newProvider
141		}
142		if newModel != "" {
143			s.Model = newModel
144		}
145	}
146	
147	// RedactionSettings configures redaction behavior beyond the default secret detection.
148	type RedactionSettings struct {
149		PII *PIISettings `json:"pii,omitempty"`
150	}
151	
152	// PIISettings configures PII detection categories.
153	// When Enabled is true, email and phone default to true; address defaults to false.
154	type PIISettings struct {
155		Enabled        bool              `json:"enabled"`
156		Email          *bool             `json:"email,omitempty"`
157		Phone          *bool             `json:"phone,omitempty"`
158		Address        *bool             `json:"address,omitempty"`
159		CustomPatterns map[string]string `json:"custom_patterns,omitempty"`
160	}
161	
162	// GetCommitLinking returns the effective commit linking mode.
163	// Returns the explicit value if set, otherwise defaults to "prompt"
164	// to preserve existing user behavior.
165	func (s *EntireSettings) GetCommitLinking() string {
166		if s.CommitLinking != "" {
167			return s.CommitLinking
168		}
169		return CommitLinkingPrompt
170	}
171	
172	// SummaryTimeoutValue returns the configured hard deadline for
173	// `entire explain --generate` summary generation. Zero means "unset" --
174	// the caller picks the default. Negative values are treated as unset.
175	func (s *EntireSettings) SummaryTimeoutValue() time.Duration {
176		if s.SummaryTimeoutSeconds < 1 {
177			return 0
178		}
179		return time.Duration(s.SummaryTimeoutSeconds) * time.Second
180	}
181	
182	// Load loads the Entire settings from .entire/settings.json,
183	// then applies any overrides from .entire/settings.local.json if it exists.
184	// Returns default settings if neither file exists.
185	// Works correctly from any subdirectory within the repository.
186	func Load(ctx context.Context) (*EntireSettings, error) {
187		// Get absolute paths for settings files
188		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
189		if err != nil {
190			settingsFileAbs = EntireSettingsFile // Fallback to relative
191		}
192		localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
193		if err != nil {
194			localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
195		}
196	
197		return loadMergedSettings(settingsFileAbs, localSettingsFileAbs)
198	}
199	
200	func loadMergedSettings(settingsFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
201		// Load base settings
202		settings, err := loadFromFile(settingsFileAbs)
203		if err != nil {
204			return nil, fmt.Errorf("reading settings file: %w", err)
205		}
206	
207		// Apply local overrides if they exist
208		localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
209		if err != nil {
210			if !os.IsNotExist(err) {
211				return nil, fmt.Errorf("reading local settings file: %w", err)
212			}
213			// Local file doesn't exist, continue without overrides
214		} else {
215			if err := mergeJSON(settings, localData); err != nil {
216				return nil, fmt.Errorf("merging local settings: %w", err)
217			}
218		}
219	
220		// Re-validate after merge. Individual files are validated by loadFromFile,
221		// but mergeJSON patches fields independently and can produce combinations
222		// (e.g. model without provider when the local override sets only a model
223		// on top of a base with no provider) that neither file alone contained.
224		if err := settings.SummaryGeneration.Validate(); err != nil {
225			return nil, fmt.Errorf("merged settings invalid: %w", err)
226		}
227	
228		return settings, nil
229	}
230	
231	// LoadFromFile loads settings from a specific file path without merging local overrides.
232	// Returns default settings if the file doesn't exist.
233	// Use this when you need to display individual settings files separately.
234	func LoadFromFile(filePath string) (*EntireSettings, error) {
235		return loadFromFile(filePath)
236	}
237	
238	// LoadFromBytes parses settings from raw JSON bytes without merging local overrides.
239	// Use this when you have settings content from a non-file source (e.g., git show).
240	func LoadFromBytes(data []byte) (*EntireSettings, error) {
241		s := &EntireSettings{Enabled: true}
242		dec := json.NewDecoder(bytes.NewReader(data))
243		dec.DisallowUnknownFields()
244		if err := dec.Decode(s); err != nil {
245			return nil, fmt.Errorf("parsing settings: %w", err)
246		}
247		return s, nil
248	}
249	
250	// loadFromFile loads settings from a specific file path.
251	// Returns default settings if the file doesn't exist.
252	func loadFromFile(filePath string) (*EntireSettings, error) {
253		settings := &EntireSettings{
254			Enabled: true, // Default to enabled
255		}
256	
257		data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
258		if err != nil {
259			if os.IsNotExist(err) {
260				return settings, nil
261			}
262			return nil, fmt.Errorf("%w", err)
263		}
264	
265		dec := json.NewDecoder(bytes.NewReader(data))
266		dec.DisallowUnknownFields()
267		if err := dec.Decode(settings); err != nil {
268			return nil, fmt.Errorf("parsing settings file: %w", err)
269		}
270	
271		// Validate commit_linking if set
272		if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
273			return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
274		}
275	
276		// SummaryGeneration is NOT validated here — individual files may
277		// legitimately contain only a model (provider comes from another file).
278		// Validation happens after merge in Load().
279	
280		return settings, nil
281	}
282	
283	// mergeJSON merges JSON data into existing settings.
284	// Only non-zero values from the JSON override existing settings.
285	func mergeJSON(settings *EntireSettings, data []byte) error {
286		// Validate that there are no unknown keys using strict decoding.
287		dec := json.NewDecoder(bytes.NewReader(data))
288		dec.DisallowUnknownFields()
289		var temp EntireSettings
290		if err := dec.Decode(&temp); err != nil {
291			return fmt.Errorf("parsing JSON: %w", err)
292		}
293	
294		// Parse into a map to check which fields are present.
295		var raw map[string]json.RawMessage
296		if err := json.Unmarshal(data, &raw); err != nil {
297			return fmt.Errorf("parsing JSON: %w", err)
298		}
299	
300		if err := mergeScalarFields(settings, raw); err != nil {
301			return err
302		}
303		if err := mergeStrategyOptions(settings, raw); err != nil {
304			return err
305		}
306		if err := mergeSummaryGeneration(settings, raw); err != nil {
307			return err
308		}
309		if err := mergeCommitLinking(settings, raw); err != nil {
310			return err
311		}
312	
313		// Merge redaction sub-fields if present (field-level, not wholesale replace).
314		if redactionRaw, ok := raw["redaction"]; ok {
315			if settings.Redaction == nil {
316				settings.Redaction = &RedactionSettings{}
317			}
318			if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
319				return fmt.Errorf("parsing redaction field: %w", err)
320			}
321		}
322	
323		return nil
324	}
325	
326	// mergeScalarFields merges simple bool, *bool, string, and int fields from raw JSON.
327	func mergeScalarFields(settings *EntireSettings, raw map[string]json.RawMessage) error {
328		if err := mergeRawBool(raw, "enabled", &settings.Enabled); err != nil {
329			return err
330		}
331		if err := mergeRawBool(raw, "local_dev", &settings.LocalDev); err != nil {
332			return err
333		}
334		if err := mergeRawBool(raw, "absolute_git_hook_path", &settings.AbsoluteGitHookPath); err != nil {
335			return err
336		}
337		if err := mergeRawBool(raw, "external_agents", &settings.ExternalAgents); err != nil {
338			return err
339		}
340		if err := mergeRawBool(raw, "vercel", &settings.Vercel); err != nil {
341			return err
342		}
343		if err := mergeRawBoolPtr(raw, "telemetry", &settings.Telemetry); err != nil {
344			return err
345		}
346		if err := mergeRawBoolPtr(raw, "sign_checkpoint_commits", &settings.SignCheckpointCommits); err != nil {
347			return err
348		}
349		if err := mergeRawStringNonEmpty(raw, "log_level", &settings.LogLevel); err != nil {
350			return err
351		}
352		if err := mergeRawInt(raw, "summary_timeout_seconds", &settings.SummaryTimeoutSeconds); err != nil {
353			return err
354		}
355		return nil
356	}
357	
358	func mergeRawBool(raw map[string]json.RawMessage, key string, dst *bool) error {
359		v, ok := raw[key]
360		if !ok {
361			return nil
362		}
363		return unmarshalField(key, v, dst)
364	}
365	
366	func mergeRawBoolPtr(raw map[string]json.RawMessage, key string, dst **bool) error {
367		v, ok := raw[key]
368		if !ok {
369			return nil
370		}
371		var b bool
372		if err := unmarshalField(key, v, &b); err != nil {
373			return err
374		}
375		*dst = &b
376		return nil
377	}
378	
379	func mergeRawStringNonEmpty(raw map[string]json.RawMessage, key string, dst *string) error {
380		v, ok := raw[key]
381		if !ok {
382			return nil
383		}
384		var s string
385		if err := unmarshalField(key, v, &s); err != nil {
386			return err
387		}
388		if s != "" {
389			*dst = s
390		}
391		return nil
392	}
393	
394	func mergeRawInt(raw map[string]json.RawMessage, key string, dst *int) error {
395		v, ok := raw[key]
396		if !ok {
397			return nil
398		}
399		return unmarshalField(key, v, dst)
400	}
401	
402	func unmarshalField(key string, data json.RawMessage, dst any) error {
403		if err := json.Unmarshal(data, dst); err != nil {
404			return fmt.Errorf("parsing %s field: %w", key, err)
405		}
406		return nil
407	}
408	
409	func mergeStrategyOptions(settings *EntireSettings, raw map[string]json.RawMessage) error {
410		optionsRaw, ok := raw["strategy_options"]
411		if !ok {
412			return nil
413		}
414		var opts map[string]any
415		if err := unmarshalField("strategy_options", optionsRaw, &opts); err != nil {
416			return err
417		}
418		if settings.StrategyOptions == nil {
419			settings.StrategyOptions = opts
420		} else {
421			for k, v := range opts {
422				settings.StrategyOptions[k] = v
423			}
424		}
425		return nil
426	}
427	
428	func mergeSummaryGeneration(settings *EntireSettings, raw map[string]json.RawMessage) error {
429		summaryRaw, ok := raw["summary_generation"]
430		if !ok {
431			return nil
432		}
433		if settings.SummaryGeneration == nil {
434			settings.SummaryGeneration = &SummaryGenerationSettings{}
435		}
436	
437		var summaryFields map[string]json.RawMessage
438		if err := unmarshalField("summary_generation", summaryRaw, &summaryFields); err != nil {
439			return err
440		}
441	
442		_, modelInOverride := summaryFields["model"]
443	
444		if providerRaw, ok := summaryFields["provider"]; ok {
445			var provider string
446			if err := unmarshalField("summary_generation.provider", providerRaw, &provider); err != nil {
447				return err
448			}
449			// If the override switches providers without also setting a model,
450			// the base's model was tuned to the old provider and would likely
451			// cause a runtime failure when handed to the new one (e.g. codex
452			// rejecting "sonnet"). Clear it so the new provider falls back to
453			// its own default.
454			if provider != settings.SummaryGeneration.Provider && !modelInOverride {
455				settings.SummaryGeneration.Model = ""
456			}
457			settings.SummaryGeneration.Provider = provider
458		}
459	
460		if modelRaw, ok := summaryFields["model"]; ok {
461			var model string
462			if err := unmarshalField("summary_generation.model", modelRaw, &model); err != nil {
463				return err
464			}
465			settings.SummaryGeneration.Model = model
466		}
467		return nil
468	}
469	
470	func mergeCommitLinking(settings *EntireSettings, raw map[string]json.RawMessage) error {
471		commitLinkingRaw, ok := raw["commit_linking"]
472		if !ok {
473			return nil
474		}
475		var cl string
476		if err := unmarshalField("commit_linking", commitLinkingRaw, &cl); err != nil {
477			return err
478		}
479		if cl == "" {
480			return nil
481		}
482		switch cl {
483		case CommitLinkingAlways, CommitLinkingPrompt:
484			settings.CommitLinking = cl
485		default:
486			return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
487		}
488		return nil
489	}
490	
491	// mergeRedaction merges redaction overrides into existing RedactionSettings.
492	// Only fields present in the override JSON are applied.
493	func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
494		var raw map[string]json.RawMessage
495		if err := json.Unmarshal(data, &raw); err != nil {
496			return fmt.Errorf("parsing redaction: %w", err)
497		}
498		if piiRaw, ok := raw["pii"]; ok {
499			if dst.PII == nil {
500				dst.PII = &PIISettings{}
501			}
502			if err := mergePIISettings(dst.PII, piiRaw); err != nil {
503				return err
504			}
505		}
506		return nil
507	}
508	
509	// mergePIISettings merges PII overrides into existing PIISettings.
510	// Only fields present in the override JSON are applied; missing fields
511	// are preserved from the base settings.
512	func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
513		var raw map[string]json.RawMessage
514		if err := json.Unmarshal(data, &raw); err != nil {
515			return fmt.Errorf("parsing pii: %w", err)
516		}
517		if v, ok := raw["enabled"]; ok {
518			if err := json.Unmarshal(v, &dst.Enabled); err != nil {
519				return fmt.Errorf("parsing pii.enabled: %w", err)
520			}
521		}
522		if v, ok := raw["email"]; ok {
523			var b bool
524			if err := json.Unmarshal(v, &b); err != nil {
525				return fmt.Errorf("parsing pii.email: %w", err)
526			}
527			dst.Email = &b
528		}
529		if v, ok := raw["phone"]; ok {
530			var b bool
531			if err := json.Unmarshal(v, &b); err != nil {
532				return fmt.Errorf("parsing pii.phone: %w", err)
533			}
534			dst.Phone = &b
535		}
536		if v, ok := raw["address"]; ok {
537			var b bool
538			if err := json.Unmarshal(v, &b); err != nil {
539				return fmt.Errorf("parsing pii.address: %w", err)
540			}
541			dst.Address = &b
542		}
543		if v, ok := raw["custom_patterns"]; ok {
544			var cp map[string]string
545			if err := json.Unmarshal(v, &cp); err != nil {
546				return fmt.Errorf("parsing pii.custom_patterns: %w", err)
547			}
548			if dst.CustomPatterns == nil {
549				dst.CustomPatterns = cp
550			} else {
551				for k, val := range cp {
552					dst.CustomPatterns[k] = val
553				}
554			}
555		}
556		return nil
557	}
558	
559	// IsSetUp returns true if Entire has been set up in the current repository.
560	// This checks if .entire/settings.json exists.
561	// Use this to avoid creating files/directories in repos where Entire was never enabled.
562	func IsSetUp(ctx context.Context) bool {
563		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
564		if err != nil {
565			return false
566		}
567		_, err = os.Stat(settingsFileAbs)
568		return err == nil
569	}
570	
571	// IsSetUpAny returns true if Entire has been set up in the current repository,
572	// checking both .entire/settings.json and .entire/settings.local.json.
573	// Use this to detect any prior setup, even if only local settings exist.
574	func IsSetUpAny(ctx context.Context) bool {
575		if IsSetUp(ctx) {
576			return true
577		}
578		localFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
579		if err != nil {
580			return false
581		}
582		_, err = os.Lstat(localFileAbs)
583		return err == nil
584	}
585	
586	// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
587	// This checks if .entire/settings.json exists AND has enabled: true.
588	// Use this for hooks that should be no-ops when Entire is not active.
589	func IsSetUpAndEnabled(ctx context.Context) bool {
590		if !IsSetUp(ctx) {
591			return false
592		}
593		s, err := Load(ctx)
594		if err != nil {
595			return false
596		}
597		return s.Enabled
598	}
599	
600	// IsCheckpointsV2Enabled checks if checkpoints v2 is enabled in settings.
601	// Returns false by default if settings cannot be loaded or the key is missing.
602	func IsCheckpointsV2Enabled(ctx context.Context) bool {
603		settings, err := Load(ctx)
604		if err != nil {
605			return false
606		}
607		return settings.IsCheckpointsV2Enabled()
608	}
609	
610	// IsCheckpointsV2OnlyEnabled checks if checkpoints should be written and pushed
611	// only via v2 refs.
612	func IsCheckpointsV2OnlyEnabled(ctx context.Context) bool {
613		s, err := Load(ctx)
614		if err != nil {
615			return false
616		}
617		return s.IsCheckpointsV2OnlyEnabled()
618	}
619	
620	// IsPushV2RefsEnabled checks if pushing v2 refs is enabled in settings.
621	// Returns false by default if settings cannot be loaded or flags are missing.
622	func IsPushV2RefsEnabled(ctx context.Context) bool {
623		s, err := Load(ctx)
624		if err != nil {
625			return false
626		}
627		return s.IsPushV2RefsEnabled()
628	}
629	
630	// IsFilteredFetchesEnabled checks if filtered fetches should be used.
631	// When enabled, filtered fetches always resolve remote names to URLs first so
632	// git does not persist promisor settings onto named remotes in local config.
633	// Returns false by default.
634	func IsFilteredFetchesEnabled(ctx context.Context) bool {
635		s, err := Load(ctx)
636		if err != nil {
637			return false
638		}
639		return s.IsFilteredFetchesEnabled()
640	}
641	
642	// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
643	// Returns false by default if settings cannot be loaded or the key is missing.
644	func IsSummarizeEnabled(ctx context.Context) bool {
645		settings, err := Load(ctx)
646		if err != nil {
647			return false
648		}
649		return settings.IsSummarizeEnabled()
650	}
651	
652	// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
653	func (s *EntireSettings) IsSummarizeEnabled() bool {
654		if s.StrategyOptions == nil {
655			return false
656		}
657		summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
658		if !ok {
659			return false
660		}
661		enabled, ok := summarizeOpts["enabled"].(bool)
662		if !ok {
663			return false
664		}
665		return enabled
666	}
667	
668	// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
669	// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
670	type CheckpointRemoteConfig struct {
671		Provider string // e.g., "github"
672		Repo     string // e.g., "org/checkpoints-repo"
673	}
674	
675	// Owner returns the owner portion of the repo field (before the slash).
676	// Returns empty string if the repo field doesn't contain a slash.
677	func (c *CheckpointRemoteConfig) Owner() string {
678		parts := strings.SplitN(c.Repo, "/", 2)
679		if len(parts) < 2 {
680			return ""
681		}
682		return parts[0]
683	}
684	
685	// GetCheckpointRemote returns the configured checkpoint remote.
686	// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
687	// Returns nil if not configured, wrong type, or missing required fields.
688	func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
689		if s.StrategyOptions == nil {
690			return nil
691		}
692		val, ok := s.StrategyOptions["checkpoint_remote"]
693		if !ok {
694			return nil
695		}
696		m, ok := val.(map[string]any)
697		if !ok {
698			return nil
699		}
700		provider, providerOK := m["provider"].(string)
701		repo, repoOK := m["repo"].(string)
702		if !providerOK || !repoOK || provider == "" || repo == "" {
703			return nil
704		}
705		if !strings.Contains(repo, "/") {
706			return nil
707		}
708		return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
709	}
710	
711	// IsCheckpointsV2Enabled checks if checkpoints v2 is enabled.
712	// Returns true when either checkpoints_v2 or checkpoints_v2_only is enabled.
713	func (s *EntireSettings) IsCheckpointsV2Enabled() bool {
714		if s.IsCheckpointsV2OnlyEnabled() {
715			return true
716		}
717		if s.StrategyOptions == nil {
718			return false
719		}
720		val, ok := s.StrategyOptions["checkpoints_v2"].(bool)
721		return ok && val
722	}
723	
724	// IsCheckpointsV2OnlyEnabled checks if checkpoints should be written and pushed
725	// only via v2 refs, with no v1 dual-write.
726	func (s *EntireSettings) IsCheckpointsV2OnlyEnabled() bool {
727		if s.StrategyOptions == nil {
728			return false
729		}
730		val, ok := s.StrategyOptions["checkpoints_v2_only"].(bool)
731		return ok && val
732	}
733	
734	// IsPushV2RefsEnabled checks if pushing v2 refs is enabled.
735	// checkpoints_v2_only forces v2 ref pushes on, regardless of push_v2_refs.
736	func (s *EntireSettings) IsPushV2RefsEnabled() bool {
737		if s.IsCheckpointsV2OnlyEnabled() {
738			return true
739		}
740		if !s.IsCheckpointsV2Enabled() {
741			return false
742		}
743		if s.StrategyOptions == nil {
744			return false
745		}
746		val, ok := s.StrategyOptions["push_v2_refs"].(bool)
747		return ok && val
748	}
749	
750	// GetFullTranscriptGenerationRetentionDays returns the retention window for
751	// archived checkpoints v2 /full/* generations. Invalid, missing, or
752	// non-positive values fall back to the documented default.
753	func (s *EntireSettings) GetFullTranscriptGenerationRetentionDays() int {
754		if s.StrategyOptions == nil {
755			return defaultGenerationRetentionDays
756		}
757	
758		val, ok := s.StrategyOptions["full_transcript_generation_retention_days"]
759		if !ok {
760			return defaultGenerationRetentionDays
761		}
762	
763		switch days := val.(type) {
764		case int:
765			if days > 0 {
766				return days
767			}
768		case float64:
769			intDays := int(days)
770			if intDays > 0 && days == float64(intDays) {
771				return intDays
772			}
773		}
774	
775		return defaultGenerationRetentionDays
776	}
777	
778	// IsFilteredFetchesEnabled checks if fetches should use --filter=blob:none.
779	// When enabled, filtered fetches always use resolved URLs rather than remote
780	// names to avoid persisting promisor settings onto named remotes.
781	func (s *EntireSettings) IsFilteredFetchesEnabled() bool {
782		if s.StrategyOptions == nil {
783			return false
784		}
785		val, ok := s.StrategyOptions["filtered_fetches"].(bool)
786		return ok && val
787	}
788	
789	// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
790	// Returns true if push_sessions is explicitly set to false.
791	func (s *EntireSettings) IsPushSessionsDisabled() bool {
792		if s.StrategyOptions == nil {
793			return false
794		}
795		val, exists := s.StrategyOptions["push_sessions"]
796		if !exists {
797			return false
798		}
799		if boolVal, ok := val.(bool); ok {
800			return !boolVal // disabled = !push_sessions
801		}
802		return false
803	}
804	
805	// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
806	// Returns false by default if settings cannot be loaded or the key is missing.
807	func IsExternalAgentsEnabled(ctx context.Context) bool {
808		s, err := Load(ctx)
809		if err != nil {
810			return false
811		}
812		return s.ExternalAgents
813	}
814	
815	// IsSignCheckpointCommitsEnabled returns true if checkpoint commits should be signed.
816	// Defaults to true when the setting is not explicitly set.
817	func (s *EntireSettings) IsSignCheckpointCommitsEnabled() bool {
818		return s.SignCheckpointCommits == nil || *s.SignCheckpointCommits
819	}
820	
821	// IsSignCheckpointCommitsEnabled checks if checkpoint commit signing is enabled in settings.
822	// Returns true by default if settings cannot be loaded or the key is missing.
823	func IsSignCheckpointCommitsEnabled(ctx context.Context) bool {
824		s, err := Load(ctx)
825		if err != nil {
826			return true
827		}
828		return s.IsSignCheckpointCommitsEnabled()
829	}
830	
831	// Save saves the settings to .entire/settings.json.
832	func Save(ctx context.Context, settings *EntireSettings) error {
833		return saveToFile(ctx, settings, EntireSettingsFile)
834	}
835	
836	// SaveLocal saves the settings to .entire/settings.local.json.
837	func SaveLocal(ctx context.Context, settings *EntireSettings) error {
838		return saveToFile(ctx, settings, EntireSettingsLocalFile)
839	}
840	
841	// saveToFile saves settings to the specified file path.
842	func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
843		// Get absolute path for the file
844		filePathAbs, err := paths.AbsPath(ctx, filePath)
845		if err != nil {
846			filePathAbs = filePath // Fallback to relative
847		}
848	
849		// Ensure directory exists
850		dir := filepath.Dir(filePathAbs)
851		if err := os.MkdirAll(dir, 0o750); err != nil {
852			return fmt.Errorf("creating settings directory: %w", err)
853		}
854	
855		data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
856		if err != nil {
857			return fmt.Errorf("marshaling settings: %w", err)
858		}
859	
860		//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
861		if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
862			return fmt.Errorf("writing settings file: %w", err)
863		}
864		return nil
865	}
